void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Reset activity increment to avoid overflow and give fresh boost
    var_inc = 1.0;

    // Backtrack to root level
    backtrack(0);

    // Phase selection: majority keep local best, some invert, some random
    int r = rand() % 100;
    if (r < 70) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 80) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // Adjust threshold to current trail size to delay immediate rephase
    threshold = trail.size();
}
